{"src/exportCsv.mjs":"/**
 * 将对象数组转换为 CSV 字符串，便于在表格软件中打开。
 *
 * 设计要点：
 * - 字段内容来自外部填写，可能包含逗号、双引号、换行等特殊字符，
 *   因此所有字段统一按 RFC 4180 规则加引号并转义内部双引号。
 * - 列顺序取所有行中出现过的键的并集，按首次出现顺序排列，
 *   保证不同行字段不一致时也能完整导出。
 * - 缺失字段输出为空字符串。
 * - 使用 CRLF 作为行分隔符，兼容 Excel 等常见表格软件。
 * - 为防止表格软件把外部内容当作公式执行（CSV 注入），
 *   对以 = + - @ 制表符或回车开头的文本前置单引号。
 * - 输出带 UTF-8 BOM，避免 Excel 打开中文乱码。
 *
 * @param {Array<Record<string, unknown>>} rows 对象数组
 * @returns {string} 可用于下载的 CSV 字符串
 */
export function exportCsv(rows) {
  if (!Array.isArray(rows) || rows.length === 0) {
    return "\uFEFF";
  }

  // 收集列名：按首次出现顺序去重
  const columns = [];
  const seen = new Set();
  for (const row of rows) {
    if (row === null || typeof row !== "object") continue;
    for (const key of Object.keys(row)) {
      if (!seen.has(key)) {
        seen.add(key);
        columns.push(key);
      }
    }
  }

  const lines = [];
  lines.push(columns.map(escapeField).join(","));

  for (const row of rows) {
    const record = row !== null && typeof row === "object" ? row : {};
    const cells = columns.map((key) => escapeField(record[key]));
    lines.push(cells.join(","));
  }

  return "\uFEFF" + lines.join("\r\n");
}

/**
 * 将单个字段值转为安全的 CSV 单元格文本。
 * @param {unknown} value
 * @returns {string}
 */
function escapeField(value) {
  let text;
  if (value === null || value === undefined) {
    text = "";
  } else if (typeof value === "object") {
    // 对象/数组等复杂值序列化为 JSON，避免出现 [object Object]
    try {
      text = JSON.stringify(value);
    } catch {
      text = String(value);
    }
  } else {
    text = String(value);
  }

  // 防 CSV 注入：以公式触发字符开头的文本前置单引号
  if (/^[=+\-@\t\r]/.test(text)) {
    text = "'" + text;
  }

  // RFC 4180：包含逗号、双引号、换行时加引号，内部双引号双写
  if (/[",\r\n]/.test(text)) {
    text = '"' + text.replace(/"/g, '""') + '"';
  }

  return text;
}
"}
